import { mkdir, writeFile } from 'node:fs/promises';
import { format } from 'prettier';
import { makeEpubFixture, type FixtureOptions } from './epub.ts';

const directory = new URL('./epubs/', import.meta.url);
await mkdir(directory, { recursive: true });
const cases: Record<string, FixtureOptions> = {
  'one-chapter': {},
  'split-chapter': {
    chapters: [
      { name: 'z.xhtml', text: 'Начало одной главы.' },
      { name: 'a.xhtml', text: 'Продолжение той же главы.' },
      { name: 'end.xhtml', text: 'Конец главы.' },
    ],
    toc: [0],
  },
  'parts-sparse-toc': {
    chapters: Array.from({ length: 4 }, (_, index) => ({
      name: `part-${String(index)}.xhtml`,
      text: `Часть ${String(index + 1)}. Самостоятельный синтетический текст.`,
    })),
    toc: [0],
  },
  epub2: { version: '2', cover: true },
  'long-russian': {
    chapters: [
      {
        name: 'long.xhtml',
        text: 'Длинный русскоязычный текст: ёж, пробелы и знаки препинания. '.repeat(
          4000,
        ),
      },
    ],
  },
  'illustrations-cover': { cover: true },
  'broken-links': { brokenLink: true },
  'missing-spine-resource': { missingChapter: 0 },
  drm: { drm: true },
  'unsafe-script': {
    unsafeMarkup: '<script>globalThis.epubUnsafe = true;</script>',
  },
};
const expected: Record<
  string,
  { linearPaths: string[]; normalizedTexts: string[] }
> = {};
for (const [name, options] of Object.entries(cases)) {
  const fixture = await makeEpubFixture(options);
  await writeFile(new URL(`${name}.epub`, directory), fixture.bytes);
  expected[name] = {
    linearPaths: fixture.linearPaths,
    normalizedTexts: fixture.expected,
  };
  if (name === 'one-chapter') {
    await writeFile(new URL('repeat-identical.epub', directory), fixture.bytes);
    await writeFile(
      new URL('damaged.epub', directory),
      fixture.bytes.slice(0, -25),
    );
  }
}
await writeFile(
  new URL('expected.json', directory),
  await format(JSON.stringify(expected), { parser: 'json' }),
);
await writeFile(
  new URL('LICENSE.txt', directory),
  'All EPUB files, metadata, illustrations and synthetic text in this directory are original test fixtures dedicated to the public domain under CC0-1.0. https://creativecommons.org/publicdomain/zero/1.0/\nGenerated by tests/fixtures/write-epubs.ts. Never seed these files into a user library.\n',
);
